
// Read CSV files generated by Scala and Spark
async function loadCSV(fileName) {
    const response = await fetch("output/" + fileName);

    if (!response.ok) {
        throw new Error("Could not load " + fileName);
    }

    const text = await response.text();

    const rows = [];
    let row = [];
    let value = "";
    let insideQuotes = false;

    for (let i = 0; i < text.length; i++) {
        const char = text[i];

        if (char === '"') {
            if (insideQuotes && text[i + 1] === '"') {
                value += '"';
                i++;
            } else {
                insideQuotes = !insideQuotes;
            }
        } else if (char === "," && !insideQuotes) {
            row.push(value);
            value = "";
        } else if ((char === "\n" || char === "\r") && !insideQuotes) {
            if (char === "\r" && text[i + 1] === "\n") i++;

            row.push(value);

            if (row.some(cell => cell.trim() !== "")) {
                rows.push(row);
            }

            row = [];
            value = "";
        } else {
            value += char;
        }
    }

    if (value !== "" || row.length > 0) {
        row.push(value);
        rows.push(row);
    }

    const headers = rows.shift();

    return rows.map(values => {
        const object = {};

        headers.forEach((header, index) => {
            object[header] = values[index] ?? "";
        });

        return object;
    });
}

// Shared zoom settings
const zoomOptions = {
    pan: {
        enabled: true,
        mode: "xy"
    },
    zoom: {
        wheel: {
            enabled: true,
            speed: 0.1
        },
        pinch: {
            enabled: true
        },
        drag: {
            enabled: false
        },
        mode: "xy"
    },
    limits: {
        x: {
            min: "original",
            max: "original"
        },
        y: {
            min: "original",
            max: "original"
        }
    }
};

// Double-click to reset graph zoom
function enableDoubleClickReset(chart) {
    chart.canvas.addEventListener("dblclick", function () {
        chart.resetZoom();
    });
}

// Store movie data for search and sorting
let allMovies = [];

// Display movies in the table
function displayMovies(movies) {
    const movieTable = document.getElementById("movieTable");

    if (movies.length === 0) {
        movieTable.innerHTML = `
            <tr>
                <td colspan="3" style="text-align:center; padding:20px;">
                    No matching movies found.
                </td>
            </tr>
        `;
    } else {
        movieTable.innerHTML = movies.map(movie => `
            <tr>
                <td>${escapeHTML(movie.title)}</td>
                <td>${movie.rating_count}</td>
                <td>${movie.average_rating} / 5</td>
            </tr>
        `).join("");
    }

    document.getElementById("movieResultCount").textContent =
        `Showing ${movies.length} of ${allMovies.length} movies`;
}

// Search and sort movies
function setupMovieControls() {

    const searchInput = document.getElementById("movieSearch");
    const sortSelect = document.getElementById("movieSort");
    const resetButton = document.getElementById("resetMovieFilters");

    function updateMovieTable() {

        const searchText = searchInput.value.trim().toLowerCase();

        let filteredMovies = allMovies.filter(movie =>
            String(movie.title).toLowerCase().includes(searchText)
        );

        const sortValue = sortSelect.value;

        if (sortValue === "rating") {
            filteredMovies.sort((a, b) =>
                Number(b.average_rating) - Number(a.average_rating)
            );
        } else if (sortValue === "count") {
            filteredMovies.sort((a, b) =>
                Number(b.rating_count) - Number(a.rating_count)
            );
        } else if (sortValue === "title") {
            filteredMovies.sort((a, b) =>
                String(a.title).localeCompare(String(b.title))
            );
        }

        displayMovies(filteredMovies);
    }

    searchInput.addEventListener("input", updateMovieTable);
    sortSelect.addEventListener("change", updateMovieTable);

    resetButton.addEventListener("click", function () {
        searchInput.value = "";
        sortSelect.value = "default";
        updateMovieTable();
    });

    updateMovieTable();
}

// Load all dashboard data
async function loadDashboard() {

    try {

        const genres = await loadCSV("genre_analysis.csv");
        const movies = await loadCSV("top_movies.csv");
        const years = await loadCSV("yearly_trends.csv");
        const users = await loadCSV("user_activity.csv");
        const ratings = await loadCSV("rating_trends.csv");
        // =========================
// KEY INSIGHTS
// =========================

// 1. Most popular genre
        const popularGenre = [...genres].sort(
            (a, b) => Number(b.total_ratings) - Number(a.total_ratings)
        )[0];

        document.getElementById("insightGenre").textContent =
            popularGenre ? popularGenre.genre : "N/A";


// 2. Highest rated movie (from top_movies.csv)
        const highestMovie = [...movies].sort(
            (a, b) => Number(b.average_rating) - Number(a.average_rating)
        )[0];

        document.getElementById("insightMovie").textContent =
            highestMovie ? highestMovie.title : "N/A";


// 3. Year with most movie releases
        const bestYear = [...years].sort(
            (a, b) => Number(b.total_movies) - Number(a.total_movies)
        )[0];

        document.getElementById("insightYear").textContent =
            bestYear ? bestYear.release_year : "N/A";


// 4. Most active user
        const activeUser = [...users].sort(
            (a, b) => Number(b.total_ratings) - Number(a.total_ratings)
        )[0];

        document.getElementById("insightUser").textContent =
            activeUser ? "User " + activeUser.userId : "N/A";

        // Update genre count
        document.getElementById("genreCount").textContent = genres.length;

        // Store movies and activate search and sorting
        allMovies = movies;
        setupMovieControls();

        // Genre chart
        const genreChart = new Chart(document.getElementById("genreChart"), {
            type: "bar",

            data: {
                labels: genres.map(item => item.genre),

                datasets: [{
                    label: "Total Ratings",
                    data: genres.map(item => Number(item.total_ratings)),
                    backgroundColor: "#3b82f6"
                }]
            },

            options: {
                indexAxis: "y",
                responsive: true,
                maintainAspectRatio: false,

                plugins: {
                    zoom: zoomOptions
                }
            }
        });

        enableDoubleClickReset(genreChart);
        // Populate genre filter
        const genreFilter = document.getElementById("genreFilter");

// Keep All Genres as the first option
        genreFilter.innerHTML = '<option value="all">All Genres</option>';

        genres.forEach(item => {
            const option = document.createElement("option");
            option.value = item.genre;
            option.textContent = item.genre;
            genreFilter.appendChild(option);
        });

        genreFilter.value = "all";

// Filter genre chart
        genreFilter.addEventListener("change", function () {
            const selectedGenre = this.value;

            const filteredGenres = selectedGenre === "all"
                ? genres
                : genres.filter(item => item.genre === selectedGenre);

            genreChart.data.labels = filteredGenres.map(item => item.genre);

            genreChart.data.datasets[0].data =
                filteredGenres.map(item => Number(item.total_ratings));

            genreChart.resetZoom();
            genreChart.update();
        });

        // Yearly movie release chart
        const yearChart = new Chart(document.getElementById("yearChart"), {
            type: "line",

            data: {
                labels: years.map(item => item.release_year),

                datasets: [{
                    label: "Movies Released",
                    data: years.map(item => Number(item.total_movies)),
                    borderColor: "#8b5cf6",
                    backgroundColor: "#c4b5fd",
                    tension: 0.3
                }]
            },

            options: {
                responsive: true,
                maintainAspectRatio: false,

                plugins: {
                    zoom: zoomOptions
                }
            }
        });

        enableDoubleClickReset(yearChart);
        // Filter yearly movie trends
        const yearFilter = document.getElementById("yearFilter");

        yearFilter.addEventListener("change", function () {
            const selectedYear = this.value;

            const filteredYears = selectedYear === "all"
                ? years
                : years.filter(item =>
                    Number(item.release_year) >= Number(selectedYear)
                );

            yearChart.data.labels =
                filteredYears.map(item => item.release_year);

            yearChart.data.datasets[0].data =
                filteredYears.map(item => Number(item.total_movies));

            yearChart.resetZoom();
            yearChart.update();
        });

        // Rating trends chart
        const ratingChart = new Chart(document.getElementById("ratingChart"), {
            type: "line",

            data: {
                labels: ratings.map(item => item.rating_date),

                datasets: [{
                    label: "Number of Ratings",
                    data: ratings.map(item => Number(item.total_ratings)),
                    borderColor: "#10b981",
                    tension: 0.3
                }]
            },

            options: {
                responsive: true,
                maintainAspectRatio: false,

                plugins: {
                    zoom: zoomOptions
                }
            }
        });

        enableDoubleClickReset(ratingChart);

        // Active users table
        document.getElementById("userTable").innerHTML =
            users.map(user => `
                <tr>
                    <td>${user.userId}</td>
                    <td>${user.total_ratings}</td>
                    <td>${user.average_user_rating} / 5</td>
                </tr>
            `).join("");

        console.log("Dashboard data loaded successfully!");

    } catch (error) {

        console.error("Dashboard loading error:", error);

        document.querySelector(".content").insertAdjacentHTML(
            "afterbegin",
            `<p style="color:red; padding:15px;">
                Unable to load dashboard data. Check that the output CSV files exist.
            </p>`
        );
    }
}

// Prevent movie titles from being interpreted as HTML
function escapeHTML(value) {
    return String(value).replace(/[&<>"']/g, char => ({
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        '"': "&quot;",
        "'": "&#39;"
    })[char]);
}

// =========================
// SIDEBAR PAGE NAVIGATION
// =========================

function setupPageNavigation() {

    const navLinks = document.querySelectorAll(".sidebar nav a");
    const sections = document.querySelectorAll(".dashboard-section");

    navLinks.forEach(link => {

        link.addEventListener("click", function(event) {

            event.preventDefault();

            // Get the section ID
            const targetId = this.getAttribute("href").substring(1);

            // Hide all sections
            sections.forEach(section => {
                section.classList.remove("active-section");
            });

            // Show selected section
            const targetSection = document.getElementById(targetId);

            if (targetSection) {
                targetSection.classList.add("active-section");
            }

            // Remove active state from all links
            navLinks.forEach(navLink => {
                navLink.classList.remove("active");
            });

            // Highlight selected link
            this.classList.add("active");

            // Scroll to top of content
            window.scrollTo({
                top: 0,
                behavior: "smooth"
            });
        });
    });

    // Show Overview when dashboard first opens
    const overview = document.getElementById("overview");

    if (overview) {
        overview.classList.add("active-section");
    }

    // Highlight Overview
    if (navLinks.length > 0) {
        navLinks[0].classList.add("active");
    }
}


// Start dashboard
loadDashboard();

// Start sidebar navigation
setupPageNavigation();
// =========================
// DOWNLOAD ANALYTICS REPORT
// =========================

function setupDownloadReport() {

    const button = document.getElementById("downloadReport");

    button.addEventListener("click", function () {

        const report = [
            ["Analytics", "Result"],
            ["Total Movies", "9742"],
            ["Total Ratings", "100836"],
            ["Total Users", "610"],
            ["Most Popular Genre", document.getElementById("insightGenre").textContent],
            ["Highest Rated Movie", document.getElementById("insightMovie").textContent],
            ["Most Productive Year", document.getElementById("insightYear").textContent],
            ["Most Active User", document.getElementById("insightUser").textContent]
        ];

        const csvContent = report.map(row =>
            row.map(value => `"${String(value).replace(/"/g, '""')}"`).join(",")
        ).join("\n");

        const blob = new Blob([csvContent], {
            type: "text/csv;charset=utf-8;"
        });

        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.download = "Media_Analytics_Report.csv";
        link.click();

        URL.revokeObjectURL(link.href);
    });
}

setupDownloadReport();
